"""
Orchestrierung der Fakturierungs- und Prämienprozesse.

Enthält drei Hauptprozesse:
- run_Sachprämienn: Export von Sach- und Hardwareprämien nach MS/OWL
- run_barpraemie: Export von Barprämien als CSV
- run_faktur: Kompletter Fakturierungsprozess (SFTP, Import, Refunds, Faktur, D365-Upload)

Voraussetzungen:
- SFTP-Credentials und Pfade in constants.py
- tabelle tb_bewegungsdaten mit Last_import-Tracking
"""

import logging
import os
from datetime import datetime, timedelta
from pathlib import Path

from ..config_service import get_sftp_esuite_config, get_sftp_order_config
from ..constants import (
    BARPRAEMIEN_ABLAGE,
    LOCAL_PATH_ESUITE,
    REMOTE_PATH_ESUITE,
    TIMEZONE,
)
from ..db.db_service import execute_dataframe_query, update_last_updated
from ..db.import_orchestrator import (
    generate_d365_accountreport,
    import_files_to_db,
    upload_d365_accountreport,
)
from ..transfer.sftp_service import (
    download_files_from_sftp,
    upload_file_to_sftp,
)
from .faktur_service import check_csv_file, faktur, praemienexport
from .refunds_service import process_refunds

logger = logging.getLogger(__name__)


def _check_last_import(report_name: str) -> bool:
    """Prüft ob für den gegebenen report ein Import erforderlich ist.

    Returns:
        True wenn Import nötig (letzter Import <= heute), False sonst.
    """
    result = execute_dataframe_query("SELECT Date(Last_import) FROM tb_bewegungsdaten WHERE report = ?", (report_name,))
    if result.empty:
        logger.error(f"Keine Bewegungsdaten für {report_name} gefunden")
        return False

    last_import_date = result.iloc[0, 0]
    if last_import_date is None:
        return False

    today = datetime.now(TIMEZONE).date()
    return bool(last_import_date <= today)


def _update_timestamp(report_name: str) -> None:
    """Aktualisiert den Last_updated-Timestamp für einen report."""
    update_last_updated(report_name, datetime.now(TIMEZONE).strftime("%Y-%m-%d %H:%M:%S"))


def run_sachpraemien(start_date: str, end_date: str) -> str:
    """Exportiert Sach- und Hardwareprämien für MS und OWL.

    Args:
        start_date: Startdatum im Format 'YYYY-MM-DD'
        end_date: Enddatum im Format 'YYYY-MM-DD'

    Returns:
        Statusmeldung des Exports.
    """
    logger.info(f"Starte Sachprämienexport von {start_date} bis {end_date}...")

    if not _check_last_import("SACHPRAEMIE"):
        return "Nicht erforderlich"

    heute = datetime.now(TIMEZONE)
    ordner_datum = heute.strftime("%Y-%m-%d")
    base_path = Path("//vam-fs.aschendorff.de/datenaustausch/Prämienmanagement")
    ordner_pfad = base_path / f"Prämien_{ordner_datum}"

    welten = ["MSL", "OWL"]
    welt_pfade = {}
    for welt in welten:
        pfad = ordner_pfad / welt
        pfad.mkdir(parents=True, exist_ok=True)
        welt_pfade[welt] = pfad

    try:
        for welt, pfad in welt_pfade.items():
            for prozedur in ["Sachpraemien", "Hardware"]:
                name = f"{prozedur}-export-{welt}-{start_date}-{end_date}"
                logger.info(f"Exportiere {prozedur} für {welt}...")
                praemienexport(
                    prozedur=prozedur, welt=welt, start_date=start_date, end_date=end_date, pfad=str(pfad), name=name
                )

        _update_timestamp("SACHPRAEMIE")
        logger.info("Sachprämienexport erfolgreich abgeschlossen")
        return "Sachprämienexport erfolgreich"

    except Exception as e:
        logger.error(f"Fehler bei der Sachprämiennabfrage: {e}", exc_info=True)
        return f"Fehler: {e}"


def run_barpraemie(start_date: str, end_date: str) -> str:
    """Exportiert Barprämien als CSV.

    Args:
        start_date: Startdatum im Format 'YYYY-MM-DD HH:MM:SS'
        end_date: Enddatum im Format 'YYYY-MM-DD HH:MM:SS'

    Returns:
        Statusmeldung des Exports.
    """
    logger.info(f"Starte Barpraemienabfrage von {start_date} bis {end_date}...")

    if not _check_last_import("BARPRAEMIE"):
        return "Nicht erforderlich"

    try:
        faktur(
            prozedur="Faktur_Barprämien",
            start_date=start_date,
            end_date=end_date,
            pfad=BARPRAEMIEN_ABLAGE,
            bereinigen="Nein",
            format_output="CSV",
            order_auschluss=False,
            kpi=False,
            uebermittelte_orders=True,
        )
        _update_timestamp("BARPRÄMIE")
        logger.info("Barpraemienabfrage erfolgreich abgeschlossen")
        return "Barpraemienabfrage erfolgreich"

    except Exception as e:
        logger.error(f"Fehler bei der Barpraemienabfrage: {e}", exc_info=True)
        return f"Fehler: {e}"


def _run_db_update() -> list[str]:
    """Führt SFTP-Download, datei-Import und D365-report aus.

    Returns:
        Log-Einträge der ausgeführten Schritte.
    """
    steps = []
    sftp_config = get_sftp_esuite_config()

    logger.info("SFTP-Download wird ausgeführt...")
    download_status = download_files_from_sftp(
        sftp_config=sftp_config,
        remote_path=REMOTE_PATH_ESUITE,
        local_path=LOCAL_PATH_ESUITE,
    )
    logger.info(f"SFTP-Download abgeschlossen: {download_status}")
    steps.append(f"SFTP-Download: {download_status}")

    logger.info("Importiere Dateien in Datenbank...")
    accountreport_processed = import_files_to_db()
    logger.info(f"datei-Import abgeschlossen: {accountreport_processed} Dateien verarbeitet")
    steps.append(f"datei-Import: {accountreport_processed} Dateien")

    logger.info("Generiere D365 AccountReport...")
    d365_report_generated = generate_d365_accountreport(accountreport_processed)
    logger.info(f"D365 AccountReport generiert: {d365_report_generated}")
    steps.append(f"D365 report: {d365_report_generated}")

    logger.info("Lade D365 AccountReport hoch...")
    uploaded_files = upload_d365_accountreport()
    logger.info(f"D365 AccountReport hochgeladen: {uploaded_files} Dateien")
    steps.append(f"D365 Upload: {uploaded_files} Dateien")

    return steps


def _run_refunds(end_date: str) -> str:
    """Führt den Refund-Prozess für den berechneten Zeitraum aus.

    Args:
        end_date: Enddatum im Format 'YYYY-MM-DD HH:MM:SS'

    Returns:
        status des Refund-Prozesses.
    """
    end_date_dt = datetime.strptime(end_date, "%Y-%m-%d %H:%M:%S")
    create_date_from = (end_date_dt - timedelta(days=5)).strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3]
    create_date_to = (end_date_dt + timedelta(days=1)).strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3]

    logger.info(f"Refund-Prozess für Zeitraum {create_date_from} bis {create_date_to}...")
    status = process_refunds(umgebung="PROD", create_date_from=create_date_from, create_date_to=create_date_to)
    logger.info(f"Refund-Prozess abgeschlossen: {status}")
    return status


def _run_faktur_export(
    prozedur: str,
    start_date: str,
    end_date: str,
    pfad: str,
    bereinigen: str,
    format_output: str,
    order_auschluss: bool,
    kpi: bool,
    uebermittelte_orders: bool,
) -> tuple[str, str]:
    """Führt Fakturierung und CSV-Prüfung aus.

    Returns:
        (filename, import_ordner) bei Erfolg. Wirft Exception bei Fehler.
    """
    logger.info("Fakturierung wird ausgeführt...")
    filename, import_ordner = faktur(
        prozedur=prozedur,
        start_date=start_date,
        end_date=end_date,
        pfad=pfad,
        bereinigen=bereinigen,
        format_output=format_output,
        order_auschluss=order_auschluss,
        kpi=kpi,
        uebermittelte_orders=uebermittelte_orders,
    )

    logger.info("CSV-datei wird überprüft...")
    check_result = check_csv_file(os.path.join(import_ordner, filename))
    if not check_result[0]:
        raise ValueError(f"CSV-datei Überprüfung fehlgeschlagen: {check_result[1]}")

    logger.info("CSV-datei Überprüfung erfolgreich")
    return filename, import_ordner


def _run_d365_upload(filename: str, import_ordner: str) -> str:
    """Lädt eine Fakturierungsdatei per SFTP zu D365 hoch.

    Returns:
        Statusmeldung.
    """
    logger.info(f"Starte Upload von {filename} zu D365...")
    sftp_config = get_sftp_order_config()
    upload_file_to_sftp(
        file=filename,
        local_file_path=import_ordner,
        remote_file_path=sftp_config.remote_path,
        sftp_config=sftp_config,
    )
    logger.info("datei erfolgreich zu D365 hochgeladen")
    return "Erfolgreich"


def run_faktur(
    prozedur: str,
    start_date: str,
    end_date: str,
    pfad: str,
    bereinigen: str,
    format_output: str,
    order_auschluss: bool,
    kpi: bool,
    uebermittelte_orders: bool,
    create_refunds: bool,
    update_db: bool,
    upload_d365: bool,
) -> str:
    """Führt den kompletten Fakturierungsprozess aus.

    Args:
        prozedur: Name der auszuführenden prozedur
        start_date: Startdatum im Format 'YYYY-MM-DD HH:MM:SS'
        end_date: Enddatum im Format 'YYYY-MM-DD HH:MM:SS'
        pfad: Zielpfad für die generierten Dateien
        bereinigen: Bereinigungsoption ('Ja'/'Nein')
        format_output: Ausgabeformat (z.B. 'CSV', 'Excel')
        order_auschluss: Flag für Orderausschluss
        KPI: Flag für KPI-Generierung
        uebermittelte_orders: Flag für übermittelte Orders
        create_refunds: Flag für Ausführung des Refund-Prozesses
        update_db: Flag für Datenbankaktualisierung (SFTP, Import, D365-report)
        upload_d365: Flag für Upload der Fakturierungsdateien zu D365

    Returns:
        Statusmeldung des Prozesses.
    """
    process_steps = []

    try:
        logger.info(f"=== Starte Fakturierung: {prozedur}, {start_date} bis {end_date} ===")

        if update_db:
            steps = _run_db_update()
            process_steps.extend(steps)
        else:
            logger.info("Datenbankaktualisierung übersprungen")
            process_steps.append("DB-Aktualisierung: Übersprungen")

        if create_refunds:
            refund_status = _run_refunds(end_date)
            process_steps.append(f"Refund-Prozess: {refund_status}")
        else:
            logger.info("Refund-Prozess übersprungen")
            process_steps.append("Refund-Prozess: Übersprungen")

        faktur_result = _run_faktur_export(
            prozedur, start_date, end_date, pfad, bereinigen, format_output, order_auschluss, kpi, uebermittelte_orders
        )
        process_steps.append("Fakturierung: Erfolgreich")

        if upload_d365:
            filename, import_ordner = faktur_result
            upload_status = _run_d365_upload(filename, import_ordner)
            process_steps.append(f"D365 Upload: {upload_status}")
        else:
            logger.info("Upload zu D365 übersprungen")
            process_steps.append("D365 Upload: Übersprungen")

        summary = f"Fakturierung erfolgreich abgeschlossen. {len(process_steps)} Schritte ausgeführt."
        logger.info(summary)
        logger.info(f"Schritte: {'; '.join(process_steps)}")
        return summary

    except Exception as e:
        error_msg = f"Fakturierung fehlgeschlagen nach Schritt {len(process_steps)}: {e}"
        logger.error(error_msg, exc_info=True)
        if process_steps:
            logger.info(f"Abgeschlossene Schritte: {'; '.join(process_steps)}")
        return error_msg
